  function deepFreeze(value) {
    if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
    for (const child of Object.values(value)) deepFreeze(child);
    return Object.freeze(value);
  }

  function character(characterId) {
    return data.characters[String(characterId || '')] || null;
  }

  function clip(characterId, clipId) {
    const entry = character(characterId);
    return entry?.clips?.[String(clipId || '')] || (entry ? entry.clips[entry.defaultClip] : null);
  }

  function listCharacters() {
    return Object.entries(data.characters).map(([id, entry]) => ({ id, ...entry }));
  }

  deepFreeze(data);

  if (typeof CharacterAnimationTuning !== 'undefined') {
    for (const [id, entry] of Object.entries(data.characters)) {
      CharacterAnimationTuning.register(id, entry.clips, entry.displayName || id);
    }
  }

  return Object.freeze({
    schemaVersion: data.schemaVersion,
    character,
    clip,
    listCharacters,
    get data() { return data; },
  });
